module lock_control (

```
	 input wire clk,
	 input wire reset,
	 input wire lock,
	 input wire unlock,
	 output reg unlocked
 );
	 reg unlocked_next = 1'b0;
	 always @(lock or unlock or unlocked) begin
		 if (reset == 1'b1) begin
			 unlocked_next = 1'b1; 
		 end else if (lock == 1'b1) begin
			 unlocked_next = 1'b0; 
		 end else if (unlock == 1'b1) begin
			 unlocked_next = 1'b1; 
		 end else begin
			 unlocked_next = unlocked; 
		 end
	 end
	 always @(posedge clk) begin
		 unlocked <= unlocked_next;
	 end
 endmodule
```

library ieee;
 use ieee.std_logic_1164.all;

 entity lock_control is

```
	 port (
		 clk : in std_logic;
		 reset : in std_logic;
		 lock : in std_logic;
		 unlock : in std_logic;
		 unlocked : out std_logic
	 );
 end entity lock_control;
 architecture behavioral of lock_control is
	 signal unlocked_reg : std_logic:=’0’;
	 signal unlocked_next : std_logic;
 begin
	 process(lock, unlock, unlocked_reg)
	 begin
		 if reset = '1' then
			 unlocked_next <= '1';
		 elsif lock = '1' then
			 unlocked_next <= '0';
		 elsif unlock = '1' then
			 unlocked_next <= '1';
		 else
			 unlocked_next <= unlocked_reg;
		 end if;
	 end process;
	 process(clk)
	 begin
		 if rising_edge(clk) then
			 unlocked_reg <= unlocked_next;
		 end if;
	 end process;
	 unlocked <= unlocked_reg;
 end architecture behavioral; 
